    """Caches values until their time-to-live expires."""

    def __init__(self, ttl_seconds: float = 60.0):
        self.ttl_seconds = ttl_seconds
        self._entries = {}

    def get_or_set(self, key: str, producer):
        """Return cached `key`, or compute it with `producer` and cache it."""
        hit = self._entries.get(key)
        now = time.monotonic()
        if hit is not None and (now - hit[1]) < self.ttl_seconds:
            return hit[0]
        value = producer()
        self._entries[key] = (value, now)
        return value

    def invalidate(self, key: str) -> None:
        """Drop a single expired or unwanted entry."""
        self._entries.pop(key, None)","truncated":false},"retrieval":{"channels":[],"seeds":[]},"route":{"depth":2,"origins":[{"neighbor":{"via":{"file":"oxidepy/__init__.py"},"relation":"imports","direction":"outgoing"}}]},"provenance_truncated":false,"relations":[{"kind":"contains_physical","from":{"file":"oxidepy/cache.py"},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}}},"basis":"syntactic"},{"kind":"contains_physical","from":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0],["__init__",0]]}}},"basis":"syntactic"},{"kind":"contains_physical","from":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0],["get_or_set",0]]}}},"basis":"syntactic"},{"kind":"contains_physical","from":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0],["invalidate",0]]}}},"basis":"syntactic"},{"kind":"defines","from":{"module":"python:oxidepy.cache"},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}}},"basis":"syntactic"},{"kind":"imports","from":{"file":"oxidepy/__init__.py"},"to":{"resolved":{"symbol":{"file":"oxidepy/cache.py","path":[["TTLCache",0]]}}},"basis":"resolved"}],"relations_truncated":false}

