{"capsule_version":2,"snapshot":{"repo":"phase3-eval","snapshot":"sha256:eccfbe9467b3b4b27f167be7b40cfc03d5a06baff395f5fc0f7d75707df7952a","derivation":"sha256:2bc670d284ea3a0cb0e224710af503eb43d1c83bda1f5b0fb3cb0ebee5b0c399"},"subject":{"candidate":{"file":"oxidepy/auth.py"}},"question":"relevance","task":{"query":"base class for delivery channels used to notify when retries give up","query_truncated":false,"query_digest":"sha256:45508182e3538219222acda7dcd5feba1ef01f5b680047d0689f3a5eb9864129"},"entity":{"kind":"file","name":"auth.py","signature":null,"entity_truncated":false,"source":{"file":"oxidepy/auth.py","start":0,"end":1645,"digest":"sha256:5df7e1bd4c0f2974f5e722fbaf21b86f1142f8125f27b8e3c7259584df80e857"},"test":false,"coverage":"complete","parent":"repository"},"snippet":{"text":""""Authentication service: login, token refresh, secure storage."""

import base64
import json

from .http_client import HttpClient


class TokenError(RuntimeError):
    pass


class TokenStore:
    """Persists access tokens for the current session."""

    def __init__(self):
        self._tokens = {}

    def save(self, session_id: str, token: str) -> None:
        self._tokens[session_id] = token

    def load(self, session_id: str):
        return self._tokens.get(session_id)


class AuthService:
    """Handles login sessions and refreshes expired auth tokens."""

    def __init__(self, client: HttpClient, store: TokenStore):
        self.client = client
        self.store = store

    def login(self, username: str, password: str) -> str:
        payload = json.dumps({"username": username, "password": password}).encode()
        body = self.client.fetch("auth/login")
        token = body.decode() or base64.b64encode(payload).decode()
        self.store.save(username, token)
        return token

    def refresh_token(self, session_id: str) -> str:
        """Exchange a stale token for a fresh one after it expires."""
        stale = self.store.load(session_id)
        if not stale:
            raise TokenError(f"no stored token for {session_id}")
        fresh = self.client.fetch("auth/refresh").decode()
        self.store.save(session_id, fresh)
        return fresh


def decode_claims(token: str) -> dict:
    """Decode the payload section of a JWT without verifying it."""
    _, payload, _ = token.split(".")
    padded = payload + "=" * (-len(payload) % 4)
    return json.loads(base64.urlsafe_b64decode(padded))
